import React, { useCallback, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_LIVEBOARD_ID } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';

export default function Dashboard() {
  const [embedError, setEmbedError] = useState<string | null>(null);
  const { hiddenActions, disabledActions } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    const msg =
      err?.data?.errorMessage ||
      err?.message ||
      (typeof err === 'object' ? JSON.stringify(err) : String(err));
    setEmbedError(msg);
    console.error('[ThoughtSpot Liveboard]', err);
  }, []);

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F5F4FA' }}>
      <div style={{ padding: '2rem 2.5rem 0' }}>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: '#130829', margin: 0 }}>
          Analytics Dashboard
        </h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '4px 0 0' }}>
          Detailed travel programme performance and spend insights
        </p>
      </div>

      <div style={{ padding: '1.5rem 2.5rem 2rem' }}>
        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '1rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 14,
              color: '#991B1B',
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}

        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 12,
            overflow: 'hidden',
            minHeight: 600,
          }}
        >
          <LiveboardEmbed
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            fullHeight
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onError={onError}
            style={{ width: '100%', height: '80vh', minHeight: 560 }}
          />
        </div>
      </div>
    </div>
  );
}
